#!/usr/bin/env npx tsx
/**
 * Apply the obvious-case translation backfills generated by build-obvious-backfills.ts.
 *
 * Before each UPDATE, snapshots the rows being changed (id, word_form, old english,
 * sentence_id) to scripts/output/backfill-obvious-rollback.json so the change is
 * reversible.
 *
 * Each operation is one (word_form, english) → new english match. Idempotent: if the
 * old english no longer matches, the UPDATE is a no-op.
 */
import * as fs from 'fs';
import * as path from 'path';
import { fileURLToPath } from 'url';

import { supabaseClient } from './utils/supabase-standalone';

const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);

interface Candidate {
  arabic: string;
  current: string;
  suggested: string;
  helper: string;
  trigger: string;
  occurrences: number;
  reasonKept: string;
  contexts: {
    sentenceId: number;
    position: number;
    sentenceArabic: string;
    sentenceEnglish: string;
  }[];
}

async function main() {
  const planPath = path.resolve(__dirname, 'output', 'backfill-obvious.json');
  const plan = JSON.parse(fs.readFileSync(planPath, 'utf8')) as { obvious: Candidate[] };
  const candidates = plan.obvious;
  console.log(`Loaded ${candidates.length} obvious-case candidates`);

  const dryRun = process.argv.includes('--dry-run');
  if (dryRun) console.log('DRY RUN — no writes will be made');

  const rollback: {
    appliedAt: string;
    operations: {
      arabic: string;
      oldEnglish: string;
      newEnglish: string;
      rows: { id: number; sentence_id: number }[];
    }[];
  } = { appliedAt: new Date().toISOString(), operations: [] };

  let totalRowsUpdated = 0;
  let opsApplied = 0;
  let opsNoop = 0;
  let opsErrored = 0;

  for (const c of candidates) {
    // Snapshot first
    const { data: rows, error: selErr } = await supabaseClient
      .from('sentence_words')
      .select('id, sentence_id')
      .eq('word_form', c.arabic)
      .eq('english', c.current);

    if (selErr) {
      console.error(`  ❌ select failed for ${c.arabic} | ${c.current}: ${selErr.message}`);
      opsErrored++;
      continue;
    }
    if (!rows || rows.length === 0) {
      opsNoop++;
      continue;
    }

    rollback.operations.push({
      arabic: c.arabic,
      oldEnglish: c.current,
      newEnglish: c.suggested,
      rows: rows.map(r => ({ id: r.id, sentence_id: r.sentence_id })),
    });

    if (!dryRun) {
      const { error: updErr, count } = await supabaseClient
        .from('sentence_words')
        .update({ english: c.suggested }, { count: 'exact' })
        .eq('word_form', c.arabic)
        .eq('english', c.current);

      if (updErr) {
        console.error(`  ❌ update failed for ${c.arabic} | ${c.current}: ${updErr.message}`);
        opsErrored++;
        continue;
      }
      const updatedCount = count ?? rows.length;
      totalRowsUpdated += updatedCount;
      opsApplied++;
      process.stdout.write(
        `\r  applied ${opsApplied}/${candidates.length}  (rows: ${totalRowsUpdated})`,
      );
    } else {
      console.log(`  [dry] ${c.arabic} | '${c.current}' → '${c.suggested}'  (${rows.length} rows)`);
      totalRowsUpdated += rows.length;
      opsApplied++;
    }
  }
  process.stdout.write('\n');

  const rollbackPath = path.resolve(__dirname, 'output', 'backfill-obvious-rollback.json');
  fs.writeFileSync(rollbackPath, JSON.stringify(rollback, null, 2));
  console.log(`\nrollback log → ${rollbackPath}`);

  console.log(`\nSummary:`);
  console.log(`  operations applied: ${opsApplied}`);
  console.log(`  operations no-op:   ${opsNoop} (rows already differ from snapshot, skipped)`);
  console.log(`  operations errored: ${opsErrored}`);
  console.log(`  total rows updated: ${totalRowsUpdated}`);
}

main().catch(e => {
  console.error(e);
  process.exit(1);
});
